const monthNames = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

const now = new Date();
const currentMonth = monthNames[now.getMonth()];

return [{
  json: {
    currentMonth: currentMonth,
    recipientEmail: $input.first().json['Email'],
    recipientName: $input.first().json['Name']
  }
}];

const agentOutput = $input.first().json.output;

const authorMatch = agentOutput.match(/AUTHOR:\s*(.+)/);
const bornMatch = agentOutput.match(/BORN:\s*(.+)/);
const titleMatch = agentOutput.match(/POEM_TITLE:\s*(.+)/);
const poemMatch = agentOutput.match(/POEM:\s*([\s\S]*?)(?=\nFUN_FACT:|$)/);
const funFactMatch = agentOutput.match(/FUN_FACT:\s*(.+)/);

const author = authorMatch ? authorMatch[1].trim() : 'Unknown Author';
const born = bornMatch ? bornMatch[1].trim() : '';
const poemTitle = titleMatch ? titleMatch[1].trim() : 'Untitled';
const poem = poemMatch ? poemMatch[1].trim() : agentOutput;
const funFact = funFactMatch ? funFactMatch[1].trim() : '';

const previousData = $('Get Current Month').first().json;

return [{
  json: {
    recipientEmail: previousData.recipientEmail,
    recipientName: previousData.recipientName,
    currentMonth: previousData.currentMonth,
    author: author,
    born: born,
    poemTitle: poemTitle,
    poem: poem,
    funFact: funFact
  }
}];
